<?php require __DIR__.'/../includes/core.php';require_login(['admin']);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';
if(in_array($action,['section','criterion','description'],true)){
  $target=isset($_POST['module_id'])?(int)$_POST['module_id']:0;
  if((int)one("SELECT COUNT(*) n FROM assignments WHERE module_id=? AND status='submitted'",[$target])['n']>0)throw new Exception('This template already has submitted evaluations and is locked. Create a new module for revised criteria.');
}
if($action==='load_personal_template'){
 $target=(int)($_POST['module_id']??0);
 $selected=one('SELECT id,name,slug FROM modules WHERE id=?',[$target]);
 if(!$selected || $selected['slug']!=='personal-evaluation') throw new Exception('Select the Personal Evaluation module to load its template.');
 $submitted=(int)(one("SELECT COUNT(*) n FROM assignments WHERE module_id=? AND status='submitted'",[$target])['n']??0);
 if($submitted) throw new Exception('This module has submitted evaluations and is locked.');
 $seed=file_get_contents(__DIR__.'/../database/self_evaluation_module.sql');
 if($seed===false) throw new Exception('Template SQL file not found.');
 // The supplied database uses MyISAM; transactions do not roll back table writes.
 // The seed is idempotent, so a retry can safely complete a partial import.
 $pdo=db();
 try {
   foreach(explode(';',$seed) as $statement){
     $statement=preg_replace('/^\s*--[^\n]*\n/m','',$statement);
     $statement=trim($statement);
     if($statement==='' || $statement==='START TRANSACTION' || $statement==='COMMIT') continue;
     $pdo->exec($statement);
   }
   $counts=one('SELECT COUNT(*) n FROM template_sections WHERE module_id=?',[$target]);
   $indicators=one('SELECT COUNT(*) n FROM criteria c JOIN template_sections s ON s.id=c.section_id WHERE s.module_id=?',[$target]);
   if((int)$counts['n']<6 || (int)$indicators['n']<30) throw new Exception('Template load incomplete. Retry to finish importing missing indicators.');
 }catch(Throwable $ex){throw $ex;}
 audit('module_configuration','load_personal_template');flash('Personal Evaluation template loaded: 6 sections, 30 indicators and rating descriptions.');go('admin/modules.php?id='.$target);
 }
 if($action==='new'){$name=trim($_POST['name']);$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',strtolower($name)),'-'));if(!$name||!$slug)throw new Exception('Enter a module name.');sql('INSERT INTO modules(name,slug,evaluator_role,rating_direction,is_active) VALUES (?,?,?,?,0)',[$name,$slug,$_POST['evaluator_role'],$_POST['rating_direction']]);$id=db()->lastInsertId();$labels=($_POST['rating_direction']==='low')?['Outstanding','Good','Satisfactory','Unsatisfactory']:['Poor','Unsatisfactory','Satisfactory','Very Satisfactory','Outstanding'];foreach($labels as $i=>$label)sql('INSERT INTO rating_options(module_id,rating,label) VALUES (?,?,?)',[$id,$i+1,$label]);}elseif($action==='toggle'){sql('UPDATE modules SET is_active=1-is_active WHERE id=?',[(int)$_POST['id']]);}elseif($action==='section'){sql('INSERT INTO template_sections(module_id,title,weight,sort_order) VALUES (?,?,?,?)',[(int)$_POST['module_id'],trim($_POST['title']),(float)$_POST['weight'],(int)$_POST['sort_order']]);}elseif($action==='criterion'){sql('INSERT INTO criteria(section_id,title,sort_order) VALUES (?,?,?)',[(int)$_POST['section_id'],trim($_POST['title']),(int)$_POST['sort_order']]);}elseif($action==='description'){sql('INSERT INTO rating_descriptions(criterion_id,rating,description) VALUES (?,?,?) ON DUPLICATE KEY UPDATE description=VALUES(description)',[(int)$_POST['criterion_id'],(int)$_POST['rating'],trim($_POST['description'])]);}audit('module_configuration',$action);flash('Module configuration saved.');go('admin/modules.php'.(isset($_POST['module_id'])?'?id='.(int)$_POST['module_id']:''));}catch(Throwable $e){$error=$e->getMessage();}}$modules=all('SELECT * FROM modules ORDER BY id');$id=(int)($_GET['id']??0);$module=$id?one('SELECT * FROM modules WHERE id=?',[$id]):null;$sections=$module?all('SELECT * FROM template_sections WHERE module_id=? ORDER BY sort_order,id',[$id]):[];$opts=$module?all('SELECT * FROM rating_options WHERE module_id=? ORDER BY rating',[$id]):[];ob_start();if($error)echo '<div class="alert error">'.h($error).'</div>';?><div class="card"><h2>Evaluation modules</h2><div class="tablewrap"><table><tr><th>Module</th><th>Evaluator</th><th>Status</th><th>Actions</th></tr><?php foreach($modules as $m){echo '<tr><td>'.h($m['name']).'</td><td>'.h($m['evaluator_role']).'</td><td>'.($m['is_active']?'Active':'Inactive').'</td><td><a class="btn alt" href="?id='.$m['id'].'">Configure</a> <form method="post" style="display:inline">'.token().'<input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.$m['id'].'"><button>'.($m['is_active']?'Deactivate':'Activate').'</button></form></td></tr>';}?></table></div></div><div class="card"><h2>Create evaluation module</h2><form method="post"><?=token()?><input type="hidden" name="action" value="new"><div class="formgrid"><div><label>Module name</label><input name="name" required></div><div><label>Evaluator role</label><select name="evaluator_role"><option>teacher</option><option>supervisor</option><option>management</option><option>admin</option><option>public</option></select></div><div><label>Best rating</label><select name="rating_direction"><option value="high">Highest number is best</option><option value="low">Lowest number is best</option></select></div></div><p><button>Create inactive module</button></p></form></div><?php if($module){?><div class="card"><h2>Configure: <?=h($module['name'])?></h2><p class="muted">Published forms should not be edited after submissions; create a new module for a new version. The app blocks destructive deletion by design.</p><?php if($module['slug']==='personal-evaluation'){?><form method="post" onsubmit="return confirm('Load the 30 Personal Evaluation indicators into this module? Existing indicators will be preserved.')"><?=token()?><input type="hidden" name="action" value="load_personal_template"><input type="hidden" name="module_id" value="<?=$id?>"><p><button type="submit">Load 30 Self-Evaluation Criteria from SQL</button></p></form><?php }?><h3>Add section</h3><form method="post"><?=token()?><input type="hidden" name="action" value="section"><input type="hidden" name="module_id" value="<?=$id?>"><div class="formgrid"><div><label>Section title</label><input name="title" required></div><div><label>Weight % (0 for unweighted)</label><input type="number" name="weight" step="0.01" value="0"></div><div><label>Order</label><input type="number" name="sort_order" value="0"></div></div><p><button>Add section</button></p></form><?php foreach($sections as $s){echo '<hr><h3>'.h($s['title']).' — '.h($s['weight']).'%</h3>'; $crit=all('SELECT * FROM criteria WHERE section_id=? ORDER BY sort_order,id',[$s['id']]);foreach($crit as $c){echo '<details><summary>'.h($c['title']).'</summary>';foreach($opts as $o){$d=one('SELECT description FROM rating_descriptions WHERE criterion_id=? AND rating=?',[$c['id'],$o['rating']]);echo '<form method="post">'.token().'<input type="hidden" name="action" value="description"><input type="hidden" name="module_id" value="'.$id.'"><input type="hidden" name="criterion_id" value="'.$c['id'].'"><input type="hidden" name="rating" value="'.$o['rating'].'"><label>'.h($o['rating'].' — '.$o['label']).'</label><textarea name="description" rows="2">'.h($d['description']??'').'</textarea><button>Save description</button></form>';}echo '</details>';}echo '<form method="post">'.token().'<input type="hidden" name="action" value="criterion"><input type="hidden" name="module_id" value="'.$id.'"><input type="hidden" name="section_id" value="'.$s['id'].'"><label>Add indicator</label><input name="title" required placeholder="Criterion / measurement variable"><label>Order</label><input type="number" name="sort_order" value="'.(count($crit)+1).'"><p><button>Add indicator</button></p></form>';}?></div><?php }layout('Evaluation module manager',ob_get_clean());